(3088760, 434368, 51185, '<td valign="top">simple, yet I love it</td>', 'simple, yet I love it', '2006-12-05 10:12:37.000000', NULL, 1),
(3088798, 434133, 67671, '<td valign="top">kinda looks like a vacume cleaner pipe, If it is, then ten out of ten for ingenuity. Nicely framed shot, and a great expression.</td>', 'kinda looks like a vacume cleaner pipe, If it is, then ten out of ten for ingenuity. Nicely framed shot, and a great expression.', '2006-12-05 10:27:02.000000', NULL, 1),
(3088829, 433798, 67671, '<td valign="top">I find the hand is a little to distracting, otherwise an excelent shot. 7</td>', 'I find the hand is a little to distracting, otherwise an excelent shot. 7', '2006-12-05 10:38:59.000000', NULL, 1),
(3088845, 434023, 30049, '<td valign="top">Not familiar with the movie so I can''t really comment as to the connection this image fits/doesn''t fit to the James Bond theme.  However, as a photograph I can say I like the way you''ve filled the frame with the lion and this photo has potential, unfortunately, it''s too blurry (can''t find anything in focus) to reach it''s full potential.  JMO of course.  Good luck in the challenge.</td>', 'Not familiar with the movie so I can''t really comment as to the connection this image fits/doesn''t fit to the James Bond theme.  However, as a photograph I can say I like the way you''ve filled the frame with the lion and this photo has potential, unfortunately, it''s too blurry (can''t find anything in focus) to reach it''s full potential.  JMO of course.  Good luck in the challenge.', '2006-12-05 10:45:29.000000', NULL, 1),
(3088853, 433197, 30049, '<td valign="top">What in the world is this?  Cool looking B/W image and the grain adds to the overall feel of it.  The far side of the hand is blown out a little.  Wait, is that an eyeglass case with glasses?  Is it burnt or something?  Sorry, not familiar with James Bond movies - perhaps that''s the issue with all the questions.  :D  Anyway, good luck in the challenge.</td>', 'What in the world is this?  Cool looking B/W image and the grain adds to the overall feel of it.  The far side of the hand is blown out a little.  Wait, is that an eyeglass case with glasses?  Is it burnt or something?  Sorry, not familiar with James Bond movies - perhaps that''s the issue with all the questions.  :D  Anyway, good luck in the challenge.', '2006-12-05 10:49:35.000000', NULL, 1);
