(3103919, 434366, 44490, '<td valign="top">Nice elements, but the image is too annoyingly yellow, giving it a comic book feel - did you not like it in white, or was you white balance off?  Consider adjusting it in Photoshop.</td>', 'Nice elements, but the image is too annoyingly yellow, giving it a comic book feel - did you not like it in white, or was you white balance off?  Consider adjusting it in Photoshop.', '2006-12-10 11:56:26.000000', NULL, 1),
(3103922, 434260, 44490, '<td valign="top">Nice pose.  Probably would be better with more DOF, overall sharpness, and lighter background for contrast with hair and gun.</td>', 'Nice pose.  Probably would be better with more DOF, overall sharpness, and lighter background for contrast with hair and gun.', '2006-12-10 11:59:06.000000', NULL, 1),
(3103926, 433978, 44490, '<td valign="top">Nice idea, pose, and gear.  The trees in the background are distracting, wish you had found an angle without them, or else used shallow(er) DOF to blur them out.</td>', 'Nice idea, pose, and gear.  The trees in the background are distracting, wish you had found an angle without them, or else used shallow(er) DOF to blur them out.', '2006-12-10 12:02:51.000000', NULL, 1),
